<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/layout.php'; require_once __DIR__ . '/includes/notifications.php';
$sent=false; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);if($email){$q=$pdo->prepare("SELECT id,full_name,email,phone FROM users WHERE email=? AND is_active=1");$q->execute([$email]);$u=$q->fetch();if($u){$code=(string)random_int(100000,999999);$pdo->prepare('INSERT INTO password_resets(user_id,otp_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))')->execute([$u['id'],password_hash($code,PASSWORD_DEFAULT)]);$body="Hello {$u['full_name']},\n\nYour Warwa password reset code is: {$code}\n\nIt expires in 10 minutes. If you did not request this, you can ignore this message.";send_notice($u['email'],'Your password reset code',$body); if(!empty($u['phone'])) send_sms((string)$u['phone'], "Warwa International School password reset code: {$code}. It expires in 10 minutes. Do not share this code."); $adminEmail=env_value('SCHOOL_EMAIL'); if($adminEmail!=='' && strtolower($adminEmail)!==strtolower($u['email'])) send_notice($adminEmail,'[Warwa Portal] Password reset requested','A password reset was requested for a student account. The OTP was sent only to the student.'); $adminPhone=env_value('SMS_ADMIN_PHONE'); if($adminPhone!=='') send_sms($adminPhone,'Warwa Portal: a student requested a password reset. The OTP was sent only to the student.');} }$sent=true;}
start_page('Reset password'); ?><section class="card auth-card"><p class="eyebrow">ACCOUNT RECOVERY</p><h1 class="card-title mt-2 text-2xl">Forgot your password?</h1><p class="muted mt-2">We’ll email a one-time code that expires after 10 minutes.</p><?php if($sent): ?><div class="alert alert-success mt-4">If an active account uses that email, a reset code has been sent.</div><form method="get" action="<?= e(app_url('reset-password.php')) ?>" class="mt-5 space-y-4"><div><label class="field-label">Email address</label><input class="field" name="email" type="email" required value="<?= e($_POST['email']??'') ?>"></div><div><label class="field-label">6-digit code</label><input class="field otp-box" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></div><button class="btn-primary w-full">Continue</button></form><?php else: ?><form method="post" class="mt-6 space-y-4"><?= csrf_field() ?><div><label class="field-label">Email address</label><input class="field" name="email" type="email" required autocomplete="email"></div><button class="btn-primary w-full">Send reset code</button></form><?php endif ?><p class="mt-5 text-center text-sm"><a class="font-bold text-teal-700" href="<?= e(app_url('login.php')) ?>">Back to sign in</a></p></section><?php end_page(); ?>
